 function handleKey(key: string) {
     if (isLocked.value) {
         return;
     }

     if (key === 'Enter') {
         if (current.value.length === WORD_LENGTH) {
             void submitGuess();
         } else {
             message.value = 'Vul 5 letters in.';
         }
     } else if (key === 'Backspace') {
