 function onKeydown(event: KeyboardEvent) {
     if (event.ctrlKey || event.metaKey || event.altKey) {
         return;
     }

     if (event.target instanceof HTMLButtonElement && event.key === 'Enter') {
         return;
     }

     handleKey(event.key);
 }

